"""The write-result 0.1 schema file is one set of bytes across the spec and both kits: generated by
tools/make-write-result-schema.py (and by the TypeScript kit's src/schema.ts) and pinned here by its
sha256, which the TypeScript kit's test pins too."""

from __future__ import annotations

import hashlib
import subprocess
import sys
from importlib import resources
from pathlib import Path

#: sha256 of src/mws_kit/write-result-0.1.schema.json, the spec's spec/shapes copy and the TypeScript kit's copy.
PINNED_SHA256 = "8929b0cf56936ba591204ffe0b0960ede0230648180c5e5458956f80ed53f730"

ROOT = Path(__file__).resolve().parent.parent


def _bytes() -> bytes:
    return resources.files("mws_kit").joinpath("write-result-0.1.schema.json").read_bytes()


def test_schema_file_has_the_pinned_sha256():
    assert hashlib.sha256(_bytes()).hexdigest() == PINNED_SHA256


def test_schema_file_is_the_generators_output():
    out = subprocess.run(
        [sys.executable, "-I", str(ROOT / "tools" / "make-write-result-schema.py")],
        check=True,
        capture_output=True,
    ).stdout
    assert out == _bytes()
